public class ASDF {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		  int sum = 5;

	        for (int i = 1; i <= 10; i++) {
	            sum = sum + i; // or sum += i;
	        }

	        System.out.println("Sum of first 10 natural numbers is: " + sum);
	    

	}

}
